package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.*;

import java.text.FieldPosition;
import java.util.Date;
import java.util.Locale;

public class AgentBRT_Lang_26_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Create a FastDateFormat instance with a specific pattern and locale
        FastDateFormat fastDateFormat = FastDateFormat.getInstance("yyyy-MM-dd", Locale.FRANCE);

        // Create a Date object to format
        Date date = new Date(0); // Epoch time

        // Format the date
        String formattedDate = fastDateFormat.format(date);

        // The expected formatted date string in the French locale
        String expectedDate = "1970-01-01";

        // Assert that the formatted date matches the expected date
        assertEquals("The formatted date does not match the expected output.", expectedDate, formattedDate);
    }
}

